def dot(a, b):
    return sum(x * y for x, y in zip(a, b))

assert dot([1, 2, 3], [4, 5, 6]) == 32
assert dot([1, 2, 3], [10]) == 10

zig_test:
test "t05 producto escalar" {
    const a = [_]i32{ 1, 2, 3 };
    const b = [_]i32{ 4, 5, 6 };
    try std.testing.expectEqual(@as(i64, 32), dotProduct(&a, &b));
    const c = [_]i32{10};
    try std.testing.expectEqual(@as(i64, 10), dotProduct(&a, &c));
    const empty = [_]i32{};
    try std.testing.expectEqual(@as(i64, 0), dotProduct(&empty, &a));
}
